SELECT "sk_timeid", "timevalue", "hourid", "hourdesc", "minuteid", "minutedesc", "secondid", "seconddesc", "markethoursflag", "officehoursflag" FROM (SELECT TRY_CAST((CAST(t.SK_TimeID AS INTEGER)) AS int) AS "sk_timeid", TRY_CAST((TRY_CAST(t.TimeValue AS TIME)) AS time) AS "timevalue", TRY_CAST((t.HourID) AS decimal(2)) AS "hourid", TRY_CAST((t.HourDesc) AS char(20)) AS "hourdesc", TRY_CAST((t.MinuteID) AS decimal(2)) AS "minuteid", TRY_CAST((CAST(t.MinuteDesc AS CHAR(20))) AS char(20)) AS "minutedesc", TRY_CAST((t.SecondID) AS decimal(2)) AS "secondid", TRY_CAST((t.SecondDesc) AS char(20)) AS "seconddesc", TRY_CAST((TRY_CAST(t.MarketHoursFlag AS BOOLEAN)) AS boolean) AS "markethoursflag", TRY_CAST((CASE WHEN LOWER(t.OfficeHoursFlag) = 'true' THEN TRUE WHEN LOWER(t.OfficeHoursFlag) = 'false' THEN FALSE ELSE NULL END) AS boolean) AS "officehoursflag" FROM Time AS t)
